"use strict";
import { useMemo } from "react";
import { useParams } from "react-router-dom";
import { Flex, Text } from "ui/src";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useEnhanceVotingRewardsWithMulticall } from "hooks/useEnhanceVotingRewardsWithMulticall";
import { useVeABXLock } from "hooks/useVeABXLocks";
import VotingRewardsModal from "pages/Dash/components/VotingRewardsModal";
import VotingRewardsTop from "pages/Dash/components/VotingRewardsTop";
import SingleVotingRewards from "pages/Dash/components/SingleVotingRewards";
function MessageCard({ message }) {
  return <Flex
    py={"$spacing48"}
    px={"$spacing24"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    justifyContent="center"
    alignItems="center"
  >
      <Text variant="body2" color={"$neutral2"} textAlign="center">
        {message}
      </Text>
    </Flex>;
}
export default function LockRewards() {
  const { lockId: lockIdParam } = useParams();
  const {
    data: lock,
    isLoading: isLockLoading,
    error: lockError
  } = useVeABXLock(lockIdParam, Boolean(lockIdParam), UniverseChainId.Mainnet);
  const locks = useMemo(() => lock ? [lock] : [], [lock]);
  const {
    results,
    isLoading: isRewardsLoading,
    error: rewardsError,
    refetch: refetchRewards
  } = useEnhanceVotingRewardsWithMulticall(locks, UniverseChainId.Mainnet);
  const defaultRewardsResult = useMemo(
    () => ({
      votedPools: [],
      rewards: [],
      canClaim: false,
      isLoading: isRewardsLoading,
      error: rewardsError,
      usedVeAbx: "0",
      refetch: refetchRewards
    }),
    [isRewardsLoading, rewardsError, refetchRewards]
  );
  const votingRewards = lock ? results[lock.id] ?? defaultRewardsResult : defaultRewardsResult;
  const loading = isLockLoading || isRewardsLoading;
  let content;
  if (!lockIdParam) {
    content = <MessageCard message="Missing lock identifier. Provide a lock id in the URL to view rewards." />;
  } else if (loading) {
    content = <MessageCard message="Loading voting rewards..." />;
  } else if (lockError || !lock) {
    content = <MessageCard message="Unable to find that veABX lock. Double-check the lock id and try again." />;
  } else if (votingRewards.error) {
    content = <MessageCard message="Something went wrong while fetching voting rewards. Please try again." />;
  } else if (!votingRewards.canClaim) {
    content = <MessageCard message="No voting rewards available. Vote for pools with this veABX lock to start earning rewards." />;
  } else {
    content = <SingleVotingRewards lock={lock} votingRewards={votingRewards} />;
  }
  return <Flex
    mt="$spacing24"
    width="100%"
    px="$spacing40"
    maxWidth={1200}
    pb={"$spacing40"}
    flexDirection="column"
    gap={"$gap24"}
    $xl={{
      px: "$spacing12",
      mx: "auto"
    }}
  >
      <VotingRewardsTop />

      <Flex className="locks" mt={"$spacing12"} flexDirection="column" gap={"$gap24"}>
        {content}
      </Flex>

      <VotingRewardsModal />
    </Flex>;
}
